71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
78	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
79	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
80	     */
81	    private static final Pattern EMAIL_PATTERN =
82	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
83	
84	    /**
85	     * Disposable email domains that are refused on create. An email whose domain (the part after the
86	     * {@code @}, compared case-insensitively) is in this set is rejected with a 400, since such
87	     * addresses are throwaway and unsuitable for contacting an owner.
88	     */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
90	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
91	
92	    /**
93	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
94	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
97	
98	    private final ClinicService clinicService;
99	
100	    private final OwnerMapper ownerMapper;
101	
102	    private final PetMapper petMapper;
103	
104	    private final VisitMapper visitMapper;
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    /**
132	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
133	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
134	     */
135	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
136	        List<String> missing = new ArrayList<>();
137	        if (isBlank(ownerFieldsDto.getFirstName())) {
138	            missing.add("firstName");
139	        }
140	        if (isBlank(ownerFieldsDto.getLastName())) {
141	            missing.add("lastName");
142	        }
143	        if (isBlank(ownerFieldsDto.getAddress())) {
144	            missing.add("address");
145	        }
146	        if (isBlank(ownerFieldsDto.getCity())) {
147	            missing.add("city");
148	        }
149	        if (isBlank(ownerFieldsDto.getTelephone())) {
150	            missing.add("telephone");
151	        }
152	        if (!missing.isEmpty()) {
153	            throw new RequiredFieldsMissingException(missing);
154	        }
155	    }
156	
157	    private static boolean isBlank(String value) {
158	        return value == null || value.isBlank();
159	    }
160	
161	    /**
162	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
163	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
164	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
165	     * normalized value is what gets stored, returned and used for every address comparison; a value
166	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
167	     * rejects it.
168	     *
169	     * @param address the raw address as supplied by the caller, may be {@code null}
170	     * @return the normalized address ({@code ""} when blank or {@code null})
171	     */
172	    private static String normalizeAddress(String address) {
173	        if (address == null) {
174	            return "";
175	        }
176	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
177	        if (collapsed.isEmpty()) {
178	            return "";
179	        }
180	        String[] tokens = collapsed.split(" ");
181	        StringBuilder sb = new StringBuilder(collapsed.length());
182	        for (int i = 0; i < tokens.length; i++) {
183	            String token = tokens[i];
184	            switch (token) {
185	                case "ST" -> token = "STREET";
186	                case "RD" -> token = "ROAD";
187	                case "AVE" -> token = "AVENUE";
188	                default -> { }
189	            }
190	            if (i > 0) {
191	                sb.append(' ');
192	            }
193	            sb.append(token);
194	        }
195	        return sb.toString();
196	    }
197	
198	    /**
199	     * Resolves and normalizes the owner's address on create, supporting both the structured form
200	     * ({@code addressLine1} / {@code addressLine2}) and the flat {@code address} form kept for
201	     * backward compatibility. Whichever address fields are supplied are normalized (see
202	     * {@link #normalizeAddress(String)}). The structured form is preferred when present: when
203	     * {@code addressLine1} is non-blank the composed {@code address} is the normalized
204	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when
205	     * {@code addressLine2} is present; otherwise the composed {@code address} is the normalized flat
206	     * {@code address}. The normalized structured fields are written back so they are stored and
207	     * returned, and the composed value is written to {@code address} so everything that reads the
208	     * address (the household hash, postcode validation and locality) uses the structured fields when
209	     * present, falling back to the flat address. When neither form supplies an address the composed
210	     * {@code address} is blank, so the required-field check rejects it.
211	     *
212	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
213	     */
214	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
215	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
216	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
217	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
218	        String composed;
219	        if (!line1.isEmpty()) {
220	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
221	        } else {
222	            composed = flat;
223	        }
224	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
225	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
226	        ownerFieldsDto.setAddress(composed);
227	    }
228	
229	    /**
230	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
231	     * A leading {@code +} and its country code are kept as given; otherwise the country code
232	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
233	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
234	     * is recognized the national number must have the exact length that code requires ({@code +61}
235	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
236	     * returned.
237	     *
238	     * @param telephone the raw telephone as supplied by the caller
239	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
240	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
241	     *     national-number length is wrong for its country code
242	     */
243	    private static String normalizeTelephone(String telephone) {
244	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
245	        String e164;
246	        if (cleaned.startsWith("+")) {
247	            e164 = "+" + cleaned.substring(1);
248	        } else {
249	            String national = cleaned;
250	            if (national.startsWith("0")) {
251	                national = national.substring(1);
252	            }
253	            e164 = "+61" + national;
254	        }
255	        String digits = e164.substring(1);
256	        if (!digits.matches("\\d{8,15}")) {
257	            throw new InvalidTelephoneException(
258	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
259	        }
260	        if (digits.startsWith("61")) {
261	            requireNationalLength(digits.substring(2), 9, "+61");
262	        } else if (digits.startsWith("1")) {
263	            requireNationalLength(digits.substring(1), 10, "+1");
264	        }
265	        return e164;
266	    }
267	
268	    /**
269	     * Enforces that the national portion of an E.164 number has the exact number of digits its
270	     * country code requires.
271	     *
272	     * @param national the national-number digits (the part after the country code)
273	     * @param expected the exact national-number length the country code requires
274	     * @param countryCode the country code, for the error message
275	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
276	     */
277	    private static void requireNationalLength(String national, int expected, String countryCode) {
278	        if (national.length() != expected) {
279	            throw new InvalidTelephoneException(
280	                "Telephone with country code '" + countryCode + "' must have " + expected
281	                    + " national digits");
282	        }
283	    }
284	
285	    /**
286	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
287	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
288	     *
289	     * @param email the raw email as supplied by the caller, may be {@code null}
290	     * @return the lower-cased email, or {@code null} when none was supplied
291	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
292	     */
293	    private static String normalizeEmail(String email) {
294	        if (email == null || email.isBlank()) {
295	            return null;
296	        }
297	        String trimmed = email.trim();
298	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
299	            throw new InvalidEmailException("Email must be a syntactically valid address");
300	        }
301	        String lowerCased = trimmed.toLowerCase(Locale.ROOT);
302	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
303	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
304	            throw new InvalidEmailException("Email domain is not allowed");
305	        }
306	        return lowerCased;
307	    }
308	
309	    /**
310	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
311	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
312	     * householdId}, where the email segment is the empty string when the owner has no email. Because
313	     * the telephone is part of the key, two owners that differ in any one segment (for example two
314	     * members of the same household with different telephones) produce different keys.
315	     *
316	     * @param normalizedTelephone the E.164 telephone of the owner
317	     * @param email the lower-cased email of the owner, may be {@code null}
318	     * @param householdId the stable household identifier of the owner, may be {@code null}
319	     * @return the derived identity key
320	     */
321	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
322	        return (normalizedTelephone == null ? "" : normalizedTelephone)
323	            + "|" + (email == null ? "" : email)
324	            + "|" + (householdId == null ? "" : householdId);
325	    }
326	
327	    /**
328	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
329	     * owner. This one check replaces the former separate telephone, email and household duplicate
330	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
331	     * segment are both allowed. Each existing owner's key is derived from its stored, already
332	     * normalized telephone, email and household identifier.
333	     *
334	     * @param identityKey the derived identity key of the owner being created
335	     * @throws DuplicateIdentityException if another owner already has this identity key
336	     */
337	    /**
338	     * The existing owners considered by the create endpoint's duplicate and identity checks:
339	     * every owner that is not soft-deleted. A soft-deleted owner retains its row but is ignored
340	     * here, so a create that would otherwise be blocked by it is allowed.
341	     *
342	     * @return a stream of the owners not flagged deleted
343	     */
344	    private java.util.stream.Stream<Owner> activeOwners() {
345	        return this.clinicService.findAllOwners().stream()
346	            .filter(existing -> !existing.isDeleted());
347	    }
348	
349	    private void rejectDuplicateIdentity(String identityKey) {
350	        boolean inUse = activeOwners()
351	            .anyMatch(existing -> identityKey.equals(
352	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
353	        if (inUse) {
354	            throw new DuplicateIdentityException(
355	                "An owner with the same identity key already exists");
356	        }
357	    }
358	
359	    /**
360	     * Rejects a create when an existing owner already belongs to the same household (i.e. carries the
361	     * same computed {@code householdId}, derived from last name and postcode), unless the request
362	     * knowingly opts in via {@code sharesHousehold}. Setting {@code sharesHousehold} bypasses this
363	     * block so the owner is created as a declared member of the existing household; without it, a
364	     * second owner in the same household is a conflict.
365	     *
366	     * @param householdId the computed household identifier of the owner being created
367	     * @param sharesHousehold whether the request opted in to sharing an existing household
368	     * @throws DuplicateHouseholdException if the household already exists and the request did not opt in
369	     */
370	    private void rejectDuplicateHousehold(String householdId, boolean sharesHousehold) {
371	        if (sharesHousehold) {
372	            return;
373	        }
374	        boolean exists = activeOwners()
375	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
376	        if (exists) {
377	            throw new DuplicateHouseholdException(
378	                "An owner with the same last name and postcode already exists");
379	        }
380	    }
381	
382	    /**
383	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
384	     * not a hard identity duplicate but shares this owner's last name (compared case-insensitively) and
385	     * postcode while carrying a different telephone. When the postcode is absent no owner can share it,
386	     * so there is never a match. When several existing owners qualify the one with the lowest id is
387	     * returned, so the result is deterministic.
388	     *
389	     * @param lastName the last name of the owner being created
390	     * @param postcode the postcode of the owner being created, may be {@code null}
391	     * @param normalizedTelephone the E.164 telephone of the owner being created
392	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
393	     */
394	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String normalizedTelephone) {
395	        if (postcode == null || postcode.isBlank()) {
396	            return null;
397	        }
398	        String normalizedLastName = normalizeName(lastName);
399	        return activeOwners()
400	            .filter(existing -> normalizedLastName.equals(normalizeName(existing.getLastName())))
401	            .filter(existing -> postcode.equals(existing.getPostcode()))
402	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
403	            .map(Owner::getId)
404	            .filter(java.util.Objects::nonNull)
405	            .min(Integer::compareTo)
406	            .orElse(null);
407	    }
408	
409	    /**
410	     * Derives the stable household identifier for an owner from its last name and postcode. The value
411	     * is the first twelve hex characters of the SHA-256 of {@code normalizedLastName + '|' + postcode}
412	     * (the last name normalized case-insensitively with surrounding whitespace trimmed; an absent
413	     * postcode contributes the empty string). Because it is a pure function of those two fields, every
414	     * owner with the same last name and postcode is assigned the same identifier automatically, without
415	     * any existing record having to be updated.
416	     *
417	     * @param lastName the last name of the owner being created
418	     * @param postcode the postcode of the owner being created, may be {@code null}
419	     * @return the stable household identifier
420	     */
421	    private static String householdId(String lastName, String postcode) {
422	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
423	        return sha256HexPrefix(key, 12);
424	    }
425	
426	    /**
427	     * The maximum number of owners a single city may contain. A create whose city already holds this
428	     * many owners is rejected, so a city never grows beyond this capacity.
429	     */
430	    private static final int CITY_CAPACITY = 50;
431	
432	    /**
433	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
434	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
435	     * trimmed. The count reflects the
436	     * state before the new owner is persisted, so it excludes the owner being created.
437	     *
438	     * @param city the city of the owner being created
439	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
440	     */
441	    private void rejectCityAtCapacity(String city) {
442	        String normalizedCity = normalizeName(city);
443	        long ownersInCity = this.clinicService.findAllOwners().stream()
444	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
445	            .count();
446	        if (ownersInCity >= CITY_CAPACITY) {
447	            throw new CityAtCapacityException(
448	                "The city already contains the maximum number of owners");
449	        }
450	    }
451	
452	    /**
453	     * The maximum number of owners that may be created on a single day. A create made once this many
454	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
455	     * owners are registered per day.
456	     */
457	    private static final int DAILY_OWNER_LIMIT = 100;
458	
459	    /**
460	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
461	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
462	     * rolled forward) registration date of the owner being created. The count reflects the state
463	     * before the new owner is persisted, so it excludes the owner being created.
464	     *
465	     * @param registrationDate the effective business-day registration date of the owner being created
466	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
467	     */
468	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
469	        long ownersToday = this.clinicService.findAllOwners().stream()
470	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
471	            .count();
472	        if (ownersToday >= DAILY_OWNER_LIMIT) {
473	            throw new DailyOwnerLimitExceededException(
474	                "The maximum number of owners for today has already been reached");
475	        }
476	    }
477	
478	    /**
479	     * The number of owners that may already exist for a business day before a create is flagged with
480	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
481	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
482	     */
483	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
484	
485	    /**
486	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
487	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
488	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
489	     * date of the owner being created. The count reflects the state before the new owner is persisted,
490	     * so it excludes the owner being created.
491	     *
492	     * @param registrationDate the effective business-day registration date of the owner being created
493	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
494	     */
495	    private boolean bulkSignupWarning(LocalDate registrationDate) {
496	        long ownersToday = this.clinicService.findAllOwners().stream()
497	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
498	            .count();
499	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
500	    }
501	
502	    /** Fixed public holidays the business-day roll skips. */
503	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
504	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
505	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
506	        LocalDate.parse("2026-12-28"));
507	
508	    /**
509	     * Rolls a registration date forward to a business day: any date landing on a Saturday, Sunday or
510	     * listed public holiday is advanced one day at a time until it reaches the next non-holiday
511	     * weekday, and any other weekday is returned unchanged.
512	     *
513	     * @param date the effective registration date, supplied or defaulted to the server date
514	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
515	     */
516	    private static LocalDate toBusinessDay(LocalDate date) {
517	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
518	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
519	                || PUBLIC_HOLIDAYS.contains(date)) {
520	            date = date.plusDays(1);
521	        }
522	        return date;
523	    }
524	
525	    /**
526	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
527	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
528	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
529	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
530	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
531	     * component: the identity is a pure region-and-hash value.
532	     *
533	     * @param postcode the postcode of the owner being created, may be {@code null}
534	     * @param normalizedTelephone the E.164 telephone of the owner being created
535	     * @param lastName the last name of the owner being created
536	     * @return the formatted customer code
537	     */
538	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
539	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
540	    }
541	
542	    /**
543	     * De-duplicates a freshly computed customer code against the customer codes already held by
544	     * existing owners. When the code is unused it is returned unchanged; otherwise {@code '-<n>'} is
545	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner carries.
546	     *
547	     * @param customerCode the computed customer code for the owner being created
548	     * @return the same code when unique, otherwise the code with a {@code '-<n>'} suffix that makes
549	     *     it unique
550	     */
551	    private String deduplicateCustomerCode(String customerCode) {
552	        Set<String> existing = new java.util.HashSet<>();
553	        for (Owner owner : this.clinicService.findAllOwners()) {
554	            if (owner.getCustomerCode() != null) {
555	                existing.add(owner.getCustomerCode());
556	            }
557	        }
558	        if (!existing.contains(customerCode)) {
559	            return customerCode;
560	        }
561	        int n = 2;
562	        while (existing.contains(customerCode + "-" + n)) {
563	            n++;
564	        }
565	        return customerCode + "-" + n;
566	    }
567	
568	    /**
569	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
570	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
571	     * {@code null}, non-numeric, or in no known range.
572	     *
573	     * @param postcode the postcode, may be {@code null}
574	     * @return the region code, or {@code 'UNKNOWN'}
575	     */
576	    private static String regionFromPostcode(String postcode) {
577	        if (postcode == null || postcode.isBlank()) {
578	            return "UNKNOWN";
579	        }
580	        int code;
581	        try {
582	            code = Integer.parseInt(postcode.trim());
583	        } catch (NumberFormatException e) {
584	            return "UNKNOWN";
585	        }
586	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
587	            int[] range = entry.getValue();
588	            if (code >= range[0] && code <= range[1]) {
589	                return entry.getKey();
590	            }
591	        }
592	        return "UNKNOWN";
593	    }
594	
595	    /**
596	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
597	     * upper-cased.
598	     *
599	     * @param value the string to hash
600	     * @param length the number of leading hex characters to return
601	     * @return the upper-cased hex prefix of the digest
602	     */
603	    private static String sha256HexPrefix(String value, int length) {
604	        try {
605	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
606	            StringBuilder sb = new StringBuilder(digest.length * 2);
607	            for (byte b : digest) {
608	                sb.append(String.format("%02x", b));
609	            }
610	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
611	        } catch (NoSuchAlgorithmException e) {
612	            throw new IllegalStateException("SHA-256 not available", e);
613	        }
614	    }
615	
616	    /**
617	     * Counts the existing owners that share the owner-to-be's first and last name, compared
618	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
619	     * new owner is persisted, so it excludes the owner being created.
620	     *
621	     * @param firstName the first name of the owner being created
622	     * @param lastName the last name of the owner being created
623	     * @return the number of existing owners with the same first and last name
624	     */
625	    private int countNamesakes(String firstName, String lastName) {
626	        String normalizedFirstName = normalizeName(firstName);
627	        String normalizedLastName = normalizeName(lastName);
628	        return (int) this.clinicService.findAllOwners().stream()
629	            .filter(existing ->
630	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
631	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
632	            .count();
633	    }
634	
635	    /**
636	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
637	     * number of existing owners already carrying the same {@code householdId}. The household
638	     * identifier is a deterministic function of last name and postcode, so a solo owner (the only one
639	     * with that identifier) is a household of one. The count includes the owner being created (hence
640	     * the {@code + 1}).
641	     *
642	     * @param householdId the stable household identifier of the owner being created
643	     * @return the number of household members after this create (always at least 1)
644	     */
645	    private int householdSize(String householdId) {
646	        if (householdId == null) {
647	            return 1;
648	        }
649	        return (int) this.clinicService.findAllOwners().stream()
650	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
651	            .count() + 1;
652	    }
653	
654	    /**
655	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
656	     * lower-casing.
657	     *
658	     * @param value the raw name, may be {@code null}
659	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
660	     */
661	    private static String normalizeName(String value) {
662	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
663	    }
664	
665	    /**
666	     * The fixed city-to-region table used to validate a postcode against its city
667	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
668	     * therefore accepts any 4-digit postcode.
669	     */
670	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
671	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
672	
673	    /**
674	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
675	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
676	     */
677	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
678	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
679	
680	    /**
681	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
682	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
683	     * when the city maps to a known region, must fall within that region's inclusive range
684	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
685	     * postcode.
686	     *
687	     * @param city the city of the owner being created
688	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
689	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
690	     *     for the city's region
691	     */
692	    private static void validatePostcode(String city, String postcode) {
693	        if (postcode == null || postcode.isBlank()) {
694	            return;
695	        }
696	        if (!postcode.matches("\\d{4}")) {
697	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
698	        }
699	        String region = CITY_REGION.get(city);
700	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
701	        if (range != null) {
702	            int value = Integer.parseInt(postcode);
703	            if (value < range[0] || value > range[1]) {
704	                throw new InvalidPostcodeException(
705	                    "Postcode is out of range for the city's region");
706	            }
707	        }
708	    }
