710	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
711	    @Override
712	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
713	        Owner owner = this.clinicService.findOwnerById(ownerId);
714	        if (owner == null) {
715	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
716	        }
717	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
