720	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
721	    @Override
722	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
723	        applyAddress(ownerFieldsDto);
724	        validateRequiredFields(ownerFieldsDto);
725	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
726	        if (registrationDate == null) {
727	            registrationDate = LocalDate.now();
728	        } else if (registrationDate.isAfter(LocalDate.now())) {
729	            throw new FutureRegistrationDateException(
730	                "registrationDate must not be later than the server date");
731	        }
732	        registrationDate = toBusinessDay(registrationDate);
733	        ownerFieldsDto.setRegistrationDate(registrationDate);
734	        rejectDailyOwnerLimit(registrationDate);
735	        rejectCityAtCapacity(ownerFieldsDto.getCity());
736	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
737	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
738	        ownerFieldsDto.setTelephone(normalizedTelephone);
739	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
740	        ownerFieldsDto.setEmail(normalizedEmail);
741	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
742	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
743	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
744	        rejectDuplicateHousehold(ownerHouseholdId, sharesHousehold);
745	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(
746	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), normalizedTelephone);
747	        HttpHeaders headers = new HttpHeaders();
748	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
749	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
750	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
751	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
752	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName())));
753	        owner.setHouseholdId(ownerHouseholdId);
754	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
755	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
756	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
757	        this.clinicService.saveOwner(owner);
758	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
759	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
760	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
761	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
762	        headers.setLocation(UriComponentsBuilder.newInstance()
763	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
764	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
765	    }
